"use strict";
/**
 * Version information for oag-mcp and the tools it pins.
 *
 * @module util/version
 */
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);

/**
 * Exact OpenAPI Generator versions that oag-mcp is tested against. SDKs
 * generated by any other version are rejected unless
 * --allow-untested-oag-version is given. Add versions here (with a fixture
 * and tests) to support more than one.
 */
export const SUPPORTED_OAG_VERSIONS = ["7.26.0"] as const;

/** The only OpenAPI Generator target supported by this release. */
export const SUPPORTED_GENERATOR = "typescript-fetch";

/** Deno versions accepted by the executor, as a semver range. */
export const DENO_VERSION_RANGE = ">=2.5.0 <3.0.0";

let cachedPackage:
  { name: string; version: string; author?: string } | undefined;

/**
 * Locate the oag-mcp package root by walking up from this module.
 *
 * @return {String} absolute directory containing oag-mcp's package.json
 */
export function packageRoot(): string {
  let dir = path.dirname(fileURLToPath(import.meta.url));
  for (let i = 0; i < 5; i++) {
    const candidate = path.join(dir, "package.json");
    if (fs.existsSync(candidate)) {
      const pkg = JSON.parse(fs.readFileSync(candidate, "utf8"));
      if (pkg.name === "oag-mcp") {
        return dir;
      }
    }
    dir = path.dirname(dir);
  }
  throw new Error("Unable to locate the oag-mcp package root");
}

/**
 * Read (once) oag-mcp's own package.json.
 *
 * @private
 */
function _package(): { name: string; version: string; author?: string } {
  if (!cachedPackage) {
    const pkg = JSON.parse(
      fs.readFileSync(path.join(packageRoot(), "package.json"), "utf8"),
    );
    // npm's "Name <email> (url)" form, or an object with a name.
    const author =
      typeof pkg.author === "string"
        ? pkg.author.replace(/\s*[<(].*$/, "").trim()
        : pkg.author?.name;
    cachedPackage = {
      name: pkg.name as string,
      version: pkg.version as string,
      author: author || undefined,
    };
  }
  return cachedPackage;
}

/**
 * Read the oag-mcp package name from package.json.
 *
 * @return {String} package name
 */
export function oagMcpName(): string {
  return _package().name;
}

/**
 * Read the oag-mcp version from package.json.
 *
 * @return {String} version string
 */
export function oagMcpVersion(): string {
  return _package().version;
}

/**
 * Read the oag-mcp author's name from package.json.
 *
 * @return {String} author name, or undefined when not set
 */
export function oagMcpAuthor(): string | undefined {
  return _package().author;
}

/**
 * Read the installed version of a dependency.
 *
 * @param {String} name - package name
 * @return {String} version, or "unknown"
 */
export function dependencyVersion(name: string): string {
  try {
    const pkgPath = require.resolve(`${name}/package.json`);
    return JSON.parse(fs.readFileSync(pkgPath, "utf8")).version;
  } catch {
    return "unknown";
  }
}
